from propostas.services import catalogo_belenus as leitura


def preencher_pelo_catalogo(apps, schema_editor):
    """Equipamentos já importados ganham papel no kit, peças por embalagem, MPPT e módulos por micro (D34)."""
    Equipamento = apps.get_model("propostas", "Equipamento")
    for e in Equipamento.objects.all():
        if e.tipo in ("estrutura", "cabo", "conector"):
            e.funcao = leitura.funcao_no_kit(e.descricao)
            e.pecas_por_embalagem = leitura.pecas_por_embalagem(e.descricao) if e.tipo != "cabo" else 1
        if e.tipo == "estrutura":
            e.espessura_mm = leitura.espessura_mm(e.descricao)
            e.tipo_estrutura = e.tipo_estrutura or leitura.tipo_estrutura(e.descricao)
        if e.tipo == "inversor":
            e.mppts = leitura.mppts(e.descricao)
        if e.tipo == "microinversor":
            e.modulos_por_micro = leitura.modulos_por_micro(e.potencia_w)
        e.save()


